UPDATE meal_conversation SET meal_time = COALESCE(#{mealTime,jdbcType=VARCHAR}, meal_time), taste = COALESCE(#{taste,jdbcType=VARCHAR}, taste)
, preference_tags = JSON_MERGE_PATCH(COALESCE(preference_tags, JSON_OBJECT()), CAST(#{tagsJson} AS JSON))
WHERE session_id = #{sessionId}

UPDATE meal_conversation
SET last_recommendation_ids = #{mealIdsJson}
WHERE session_id = #{sessionId}
